import json
import yaml

from quilldown_spec import Heading


def test_load_json_heading():
    json_data = r"""
    {
      "kind": "heading",
      "level": 1,
      "content": []
    }
    """
    data = json.loads(json_data, strict=False)
    instance = Heading.load(data)
    assert instance is not None
    assert instance.kind == "heading"
    assert instance.level == 1


def test_load_yaml_heading():
    yaml_data = r"""
    kind: heading
    level: 1
    content: []

    """
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = Heading.load(data)
    assert instance is not None
    assert instance.kind == "heading"
    assert instance.level == 1


def test_roundtrip_json_heading():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "kind": "heading",
      "level": 1,
      "content": []
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = Heading.load(original_data)
    saved_data = instance.save()
    reloaded = Heading.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "heading"
    assert reloaded.level == 1


